# Beyond LLM-as-judge, we measure **recall@k** — did the assistant retrieve the most relevant documents? This is especially important for a grounded knowledge assistant.

# %%
# Compute recall@k: what fraction of truly relevant docs did the assistant retrieve?
# For this question, only LHIND-2024-LEAVE is directly relevant
true_relevant = {"LHIND-2024-LEAVE"}  # Ground truth: only this is essential
retrieved = set(retrieved_docs)  # What the assistant actually retrieved

recall_at_k = len(retrieved & true_relevant) / len(true_relevant)

print(f"True relevant documents: {true_relevant}")
print(f"Retrieved documents: {retrieved}")
print(f"Recall@k (k={len(retrieved_docs)}): {recall_at_k:.2%}")
print()
if recall_at_k == 1.0:
    print("✅ Perfect recall: all relevant documents retrieved")
else:
    print("⚠️ Partial recall: some relevant documents missed")

