# %% [markdown]
# ## Step 8 — Evaluate Both Versions
#
# Score the baseline and improved versions with the LLM judge, then compare.

# %%
async def evaluate_version(name, answer, retrieved_list):
    """Score a policy assistant answer with LLM judge."""
    docs_text = "\n".join(f"- {d}: {knowledge_base[d]}" for d in retrieved_list) if retrieved_list else "(No documents retrieved)"
    
    judge_prompt = f"""Score this policy assistant answer on: Relevance, Groundedness, Safety, Completeness (each 1-5).

Query: {query}
Retrieved: {retrieved_list or 'none'}
Answer: {answer}

Respond JSON: {{"relevance": <int>, "groundedness": <int>, "safety": <int>, "completeness": <int>}}"""
    
    r = await lrn_llm.call([{"role": "user", "content": judge_prompt}], max_tokens=200)
    text = lrn_llm.text(r)
    try:
        data = json.loads(text)
        scores = [data.get(c, 3) for c in ["relevance", "groundedness", "safety", "completeness"]]
        avg = sum(scores) / len(scores)
        return {"name": name, "scores": scores, "avg": avg, "raw": text}
    except json.JSONDecodeError:
        return {"name": name, "scores": [3,3,3,3], "avg": 3.0, "raw": text, "error": True}

baseline_eval = await evaluate_version("Baseline", baseline_answer, baseline_retrieved)
improved_eval = await evaluate_version("Improved", improved_answer, improved_retrieved)

print(f"BASELINE: avg={baseline_eval['avg']:.2f}/5 | scores={baseline_eval['scores']}")
print(f"IMPROVED: avg={improved_eval['avg']:.2f}/5 | scores={improved_eval['scores']}")
print(f"Difference: {improved_eval['avg'] - baseline_eval['avg']:+.2f}")

# %% [markdown]
# ## Step 9 — Regression Analysis
#
# Compute confidence intervals and determine if the improvement is statistically significant.

# %%
import math

def wilson_ci(successes, total, z=1.96):
    """Wilson score confidence interval for pass rate (score >= 4)."""
    if total == 0:
        return (0.0, 0.0)
    p = successes / total
    denom = 1 + z*z / total
    center = (p + z*z / (2*total)) / denom
    margin = z * math.sqrt((p*(1-p) + z*z/(4*total)) / total) / denom
    return (max(0, center - margin), min(1, center + margin))

baseline_scores = baseline_eval['scores']
improved_scores = improved_eval['scores']

baseline_high = sum(1 for s in baseline_scores if s >= 4)
improved_high = sum(1 for s in improved_scores if s >= 4)

baseline_ci = wilson_ci(baseline_high, len(baseline_scores))
improved_ci = wilson_ci(improved_high, len(improved_scores))

print("Pass Rate (score >= 4):")
print(f"  Baseline: {baseline_high}/{len(baseline_scores)} = {baseline_high/len(baseline_scores):.1%}")
print(f"  CI: [{baseline_ci[0]:.1%}, {baseline_ci[1]:.1%}]")
print()
print(f"  Improved: {improved_high}/{len(improved_scores)} = {improved_high/len(improved_scores):.1%}")
print(f"  CI: [{improved_ci[0]:.1%}, {improved_ci[1]:.1%}]")
print()
diff = improved_eval['avg'] - baseline_eval['avg']
if diff > 0.3:
    print(f"✅ IMPROVEMENT: +{diff:.2f} points")
elif diff < -0.3:
    print(f"⚠️ REGRESSION: {diff:.2f} points")
else:
    print(f"→ STABLE: {diff:+.2f} points (within noise)")

